import type { Metadata, Viewport } from "next";
import { site, siteUrl, type Lang } from "@/content/site";
import { getDictionary, homePath } from "./i18n";

export const viewport: Viewport = {
  themeColor: "#faf7f2",
  width: "device-width",
  initialScale: 1,
};

// Generated by app/og.png/route.tsx (replace with a photo later if you like)
const ogImage = {
  url: "/og.png",
  width: 1200,
  height: 630,
  alt: "Chez Vous MTL — Montréal",
};

export function buildMetadata(lang: Lang): Metadata {
  const t = getDictionary(lang).meta;
  return {
    metadataBase: new URL(siteUrl),
    title: t.title,
    description: t.description,
    keywords: t.keywords,
    applicationName: site.name,
    alternates: {
      canonical: homePath(lang),
      languages: { "fr-CA": "/", "en-CA": "/en/", "x-default": "/" },
    },
    openGraph: {
      type: "website",
      siteName: site.name,
      title: t.title,
      description: t.description,
      url: homePath(lang),
      locale: lang === "fr" ? "fr_CA" : "en_CA",
      alternateLocale: lang === "fr" ? ["en_CA"] : ["fr_CA"],
      images: [ogImage],
    },
    twitter: {
      card: "summary_large_image",
      title: t.title,
      description: t.description,
      images: [ogImage.url],
    },
    robots: { index: true, follow: true },
  };
}

/** schema.org structured data so Google understands the business. */
export function jsonLd(lang: Lang) {
  const t = getDictionary(lang).meta;
  return {
    "@context": "https://schema.org",
    "@type": "LocalBusiness",
    name: site.name,
    description: t.description,
    url: `${siteUrl}${homePath(lang)}`,
    email: site.email,
    telephone: site.phoneE164,
    priceRange: "$$$",
    address: {
      "@type": "PostalAddress",
      addressLocality: site.city,
      addressRegion: site.region,
      addressCountry: site.country,
    },
    areaServed: [
      "Montréal",
      "Laval",
      "Longueuil",
      "Rive-Sud",
      "Rive-Nord",
      "West Island",
    ],
    sameAs: [`https://www.instagram.com/${site.instagram}`],
  };
}
